use clap::{Parser,Subcommand};
use futures_util::StreamExt;
use tokio::io::AsyncWriteExt;
#[derive(Parser)]
#[command(version,about="Depot artifact client")]
struct Args {
 #[arg(long,global=true,default_value="http://127.0.0.1:3000")] server:String,
 #[arg(long,global=true)] json:bool,
 #[command(subcommand)] command:Command,
}
#[derive(Subcommand)]
enum Command {
 Health,
 RepoCreate {name:String,#[arg(long,default_value="")] description:String},
 RepoList {#[arg(long,default_value="1")] page:u64,#[arg(long,default_value="20")] page_size:u64},
 Upload {repo:String,name:String,version:String,file:std::path::PathBuf},
 List {repo:String,#[arg(long,default_value="")] prefix:String,#[arg(long,default_value="1")] page:u64,#[arg(long,default_value="20")] page_size:u64},
 Info {repo:String,name:String,version:String},
 Download {repo:String,name:String,version:String,output:std::path::PathBuf},
 Delete {repo:String,name:String,version:String},
}
fn validate(c:&Command)->bool {
 use depot_domain::identifier;
 let valid=|s:&str|identifier(s).is_ok();
 match c {
 Command::RepoCreate{name,..}=>valid(name),
 Command::RepoList{page,page_size}=>*page>0&&*page_size>0&&*page_size<=100,
 Command::List{repo,page,page_size,..}=>valid(repo)&&*page>0&&*page_size>0&&*page_size<=100,
 Command::Upload{repo,name,version,..}|Command::Info{repo,name,version}|Command::Download{repo,name,version,..}|Command::Delete{repo,name,version}=>valid(repo)&&valid(name)&&valid(version),
 Command::Health=>true,
 }
}
pub async fn run()->i32 {
 let args=Args::parse();
 if !validate(&args.command){eprintln!("invalid identifier or pagination");return 2;}
 match request(args).await {Ok(())=>0,Err((code,message))=>{eprintln!("{message}");code}}
}
async fn request(a:Args)->Result<(),(i32,String)> {
 let client=reqwest::Client::builder().timeout(std::time::Duration::from_secs(45)).build().map_err(transport)?;
 let base=a.server.trim_end_matches('/');
 let path=|r:&str,n:&str,v:&str|format!("{base}/api/repos/{r}/artifacts/{n}/{v}");
 let request=match &a.command {
 Command::Health=>client.get(format!("{base}/health")),
 Command::RepoCreate{name,description}=>client.post(format!("{base}/api/repos")).json(&serde_json::json!({"name":name,"description":description})),
 Command::RepoList{page,page_size}=>client.get(format!("{base}/api/repos?page={page}&pageSize={page_size}")),
 Command::Upload{repo,name,version,file}=>{
  let f=tokio::fs::File::open(file).await.map_err(transport)?;
  let size=f.metadata().await.map_err(transport)?.len();
  client.put(path(repo,name,version)).header("content-length",size).header("content-type","application/octet-stream").body(reqwest::Body::wrap_stream(tokio_util::io::ReaderStream::with_capacity(f,65536)))
 },
 Command::List{repo,prefix,page,page_size}=>client.get(format!("{base}/api/repos/{repo}/artifacts")).query(&[("prefix",prefix.clone()),("page",page.to_string()),("pageSize",page_size.to_string())]),
 Command::Info{repo,name,version}=>client.get(path(repo,name,version)),
 Command::Download{repo,name,version,..}=>client.get(format!("{}/download",path(repo,name,version))),
 Command::Delete{repo,name,version}=>client.delete(path(repo,name,version)),
 };
 let response=request.send().await.map_err(transport)?;
 let status=response.status();
 if !status.is_success(){let code=match status.as_u16(){400=>2,404|409=>3,_=>1};return Err((code,response.text().await.unwrap_or_else(|_|"response failed".into())));}
 if let Command::Download{output,..}=a.command {
  let temp=output.with_extension(format!("part-{}",std::process::id()));
  let mut file=tokio::fs::OpenOptions::new().write(true).create_new(true).open(&temp).await.map_err(transport)?;
  let result=async {
   let mut stream=response.bytes_stream();
   while let Some(bytes)=stream.next().await {file.write_all(&bytes.map_err(transport)?).await.map_err(transport)?;}
   file.flush().await.map_err(transport)?;drop(file);tokio::fs::rename(&temp,&output).await.map_err(transport)?;
   Ok::<(),(i32,String)>(())
  }.await;
  if result.is_err(){let _=tokio::fs::remove_file(&temp).await;}result?;
  println!("{}",serde_json::json!({"downloaded":output}));
 }else if status.as_u16()==204 {println!("{}",serde_json::json!({"deleted":true}));}
 else {println!("{}",response.text().await.map_err(transport)?);}
 Ok(())
}
fn transport(e:impl std::fmt::Display)->(i32,String){(1,e.to_string())}

use axum::{body::Body,extract::{DefaultBodyLimit,Path,RawQuery,State},http::{header,StatusCode},response::{IntoResponse,Response},routing::{get,put},Json,Router};
use depot_domain::{pagination,Repository,Artifact,Page};
use depot_store::{Store,Error};
use futures_util::StreamExt;
use serde::Deserialize;
use std::sync::Arc;
type Db=State<Arc<Store>>;
struct ApiError(Error);
impl From<Error> for ApiError {fn from(e:Error)->Self{Self(e)}}
impl IntoResponse for ApiError {
 fn into_response(self)->Response {
  let (status,code,message)=match self.0 {Error::Invalid=>(StatusCode::BAD_REQUEST,"invalid","invalid request"),Error::Missing=>(StatusCode::NOT_FOUND,"not_found","resource not found"),Error::Conflict=>(StatusCode::CONFLICT,"conflict","immutable identity already exists"),Error::Storage=>(StatusCode::INTERNAL_SERVER_ERROR,"storage","storage operation failed")};
  (status,Json(serde_json::json!({"error":{"code":code,"message":message}}))).into_response()
 }
}
fn paging(q:&Option<String>)->Result<(u64,u64),ApiError> {
 let find=|key:&str|q.as_deref().unwrap_or("").split('&').find_map(|s|s.split_once('=').filter(|(k,_)|*k==key).map(|(_,v)|v));
 pagination(find("page"),find("pageSize")).map_err(|_|ApiError(Error::Invalid))
}
pub fn router(store:Arc<Store>)->Router {
 Router::new().route("/health",get(||async{Json(serde_json::json!({"status":"ok"}))}))
 .route("/api/repos",get(repos).post(create))
 .route("/api/repos/{repo}",get(repo))
 .route("/api/repos/{repo}/artifacts",get(artifacts))
 .route("/api/repos/{repo}/artifacts/{name}/{version}",put(upload).get(info).delete(delete))
 .route("/api/repos/{repo}/artifacts/{name}/{version}/download",get(download))
 .fallback(||async{ApiError(Error::Missing)})
 .layer(DefaultBodyLimit::disable()).with_state(store)
}
#[derive(Deserialize)]
struct NewRepo {name:String,#[serde(default)] description:String}
async fn create(State(db):Db,input:Result<Json<NewRepo>,axum::extract::rejection::JsonRejection>)->Result<impl IntoResponse,ApiError> {
 let Json(v)=input.map_err(|_|ApiError(Error::Invalid))?;
 Ok((StatusCode::CREATED,Json(db.create_repo(&v.name,&v.description)?)))
}
async fn repos(State(db):Db,RawQuery(q):RawQuery)->Result<Json<Page<Repository>>,ApiError>{let(p,s)=paging(&q)?;Ok(Json(db.repos(p,s)?))}
async fn repo(State(db):Db,Path(r):Path<String>)->Result<Json<Repository>,ApiError>{Ok(Json(db.repo(&r)?))}
async fn artifacts(State(db):Db,Path(r):Path<String>,RawQuery(q):RawQuery)->Result<Json<Page<Artifact>>,ApiError>{
 let(p,s)=paging(&q)?;let prefix=q.as_deref().unwrap_or("").split('&').find_map(|s|s.strip_prefix("prefix=")).unwrap_or("");
 Ok(Json(db.artifacts(&r,prefix,p,s)?))
}
async fn info(State(db):Db,Path((r,n,v)):Path<(String,String,String)>)->Result<Json<Artifact>,ApiError>{Ok(Json(db.artifact(&r,&n,&v)?))}
async fn upload(State(db):Db,Path((r,n,v)):Path<(String,String,String)>,headers:axum::http::HeaderMap,body:Body)->Result<impl IntoResponse,ApiError>{
 let content_type=headers.get(header::CONTENT_TYPE).and_then(|v|v.to_str().ok()).unwrap_or("application/octet-stream");
 let stream=body.into_data_stream().map(|r|r.map(|b|b.to_vec()).map_err(|e|e.to_string()));
 Ok((StatusCode::CREATED,Json(db.upload(&r,&n,&v,content_type,stream).await?)))
}
async fn download(State(db):Db,Path((r,n,v)):Path<(String,String,String)>)->Result<Response,ApiError>{
 let(a,file)=db.download(&r,&n,&v).await?;
 let stream=tokio_util::io::ReaderStream::with_capacity(file,65536);
 Response::builder().status(200).header(header::CONTENT_LENGTH,a.size).header(header::CONTENT_TYPE,a.content_type).header(header::ETAG,format!("\"{}\"",a.sha256)).body(Body::from_stream(stream)).map_err(|_|ApiError(Error::Storage))
}
async fn delete(State(db):Db,Path((r,n,v)):Path<(String,String,String)>)->Result<StatusCode,ApiError>{db.delete(&r,&n,&v).await?;Ok(StatusCode::NO_CONTENT)}

mod api;
use std::sync::Arc;
#[tokio::main]
async fn main() {
 if let Err(e)=run().await { eprintln!("Depot startup failed: {e}");std::process::exit(1); }
}
async fn run()->Result<(),Box<dyn std::error::Error>> {
 let addr=std::env::var("DEPOT_LISTEN").unwrap_or("127.0.0.1:3000".into());
 let data=std::env::var("DEPOT_DATA").unwrap_or("depot-data".into());
 let store=Arc::new(depot_store::Store::open(data)?);
 let listener=tokio::net::TcpListener::bind(&addr).await?;
 println!("LISTEN {}",listener.local_addr()?);
 axum::serve(listener,api::router(store)).with_graceful_shutdown(async {let _=tokio::signal::ctrl_c().await;}).await?;
 Ok(())
}
